# area: gradual_any
# hypothesis: Any is accepted where int is required, object is rejected there, and at runtime the Any-typed call with a str raises TypeError that the checkers should not have hidden.
from typing import Any, assert_type, reveal_type


def as_int(x: int) -> int:
    return x + 1


def relay_any(a: Any) -> int:
    return as_int(a)


def relay_object(o: object) -> int:
    return as_int(o)  # expect-error


def passthrough(a: Any) -> Any:
    return a


y = passthrough(5)
reveal_type(y)
assert_type(as_int(y), int)
print(relay_any(4))
try:
    relay_any('9')
except TypeError:
    print('any: TypeError at runtime')
try:
    relay_object('9')
except TypeError:
    print('object: TypeError at runtime')
